seen={}
pat=re.compile(r'\[(the user[^\]]*?)\]\n((?:\s+[0-9a-f]{8}\|.*(?:\n(?!\s+\[|===|\s+[0-9a-f]{8}\|).*)*\n?)+)')
def texts(d):
    t=d.get('type')
    if t=='user':
        c=d['message']['content']
        if isinstance(c,str): yield 'user-str',c
        else:
            for b in c:
                if b.get('type')=='tool_result':
                    x=b['content']
                    yield 'toolresult',(x if isinstance(x,str) else '\n'.join(y.get('text','') for y in x if isinstance(y,dict)))
