out=[]
for ln,l in enumerate(open(f,errors='replace'),1):
    if 'the user' not in l or ('|' not in l): continue
    try: d=json.loads(l)
    except: continue
    for kind,x in texts(d):
        for m in pat.finditer(x):
            who=m.group(1); body=m.group(2)
            for cm in re.finditer(r'([0-9a-f]{8})\| (.*?)(?=\n\s+[0-9a-f]{8}\||\Z)',body,re.S):
                key=(cm.group(1),cm.group(2)[:80])
                if key in seen: continue
                seen[key]=1
                out.append({'ln':ln,'ts':d.get('timestamp'),'kind':kind,'who':who,'cid':cm.group(1),'text':cm.group(2).strip()})
json.dump(out,open('page_comments.json','w'))
print(len(out))
for o in out:
    if kw.search(o['text']): print(o['ts'],o['ln'],o['kind'],o['who'][:60],o['cid'],len(o['text']),o['text'][:200].replace('\n',' '))
EOF
